class Pedido {
  private constructor(private itens: Item[], private status: Status) {}
  static criar(itens: Item[]) {
    if (itens.length === 0) throw new Error("Pedido precisa de ao menos um item")
    return new Pedido(itens, Status.PENDENTE)
  }
  calcularTotal() { return this.itens.reduce((s, i) => s + i.preco, 0) }
}

