class CriarPedidoController {
  constructor(private useCase: CriarPedidoUseCase) {}
  async handle(req: Request, res: Response) {
    const pedido = await this.useCase.execute({ itens: req.body.itens })
    res.status(201).json({ id: pedido.id, total: pedido.calcularTotal() })
  }
}

class PedidoRepositoryPrisma implements PedidoRepository {
  async salvar(pedido: Pedido) {
    await prisma.pedido.create({ data: pedido.toPersistence() })
  }
}

