// Viola SRP: gera relatório E salva em arquivo E envia email
class Relatorio { gerar() {}; salvarArquivo() {}; enviarEmail() {} }

// Respeita SRP: cada responsabilidade em uma classe
class GeradorRelatorio { gerar() {} }
class ArmazenadorArquivo { salvar(dados) {} }
class EnviadorEmail { enviar(destino, conteudo) {} }

interface CalculadoraDesconto { calcular(valor: number): number }
class DescontoNatal implements CalculadoraDesconto { calcular(v) { return v * 0.9 } }
// Novo desconto: nova classe, sem tocar nas existentes
class DescontoBlackFriday implements CalculadoraDesconto { calcular(v) { return v * 0.5 } }

// Viola LSP: Quadrado herda de Retangulo mas quebra a expectativa de largura/altura independentes
class Retangulo { setLargura(l) {}; setAltura(a) {} }
class Quadrado extends Retangulo {
  setLargura(l) { this.largura = this.altura = l } // efeito colateral inesperado
}

// Viola ISP: toda impressora precisa implementar métodos que não usa
